            let raw = Value::F64(cv.as_num());
            if let Some(x) = conv_expr::eval_with("sprintf(\"%.2g\",$val)", &cv, &ctx) { cv = x; }
            tags.push(mk("TargetAperture", 0x4, cv.as_string(), raw, GRP0, GRP1, GRP2, PRIO));
