            let mut cv = base;
            let raw = Value::F64(cv.as_num());
            if let Some(x) = conv_expr::eval_with("\"$val mm\"", &cv, &ctx) { cv = x; }
            tags.push(mk("FocalLength", 0x1d, cv.as_string(), raw, GRP0, GRP1, GRP2, PRIO));
