        let ctx = Ctx { make, model, file_type, dm };
        let mut cv = Conv::Str(text);
        let rc = conv_expr::eval_with("$val =~ /^\\x89PNG/s ? \"PNG\" : ($val =~ /^\\xff\\xd8\\xff/ ? \"JPG\" : \"DAT\")", &cv, &ctx);
